const arcanosMayores=["El Loco","El Mago","La Sacerdotisa","La Emperatriz","El Emperador","El Sumo Sacerdote","Los Enamorados","El Carro","La Fuerza","El Ermitaño","La Rueda de la Fortuna","La Justicia","El Colgado","La Muerte","La Templanza","El Diablo","La Torre","La Estrella","La Luna","El Sol","El Juicio","El Mundo"],imagenesCartas={"El Loco":"00.jpg","El Mago":"01.jpg","La Sacerdotisa":"02.jpg","La Emperatriz":"03.jpg","El Emperador":"04.jpg","El Sumo Sacerdote":"05.jpg","Los Enamorados":"06.jpg","El Carro":"07.jpg","La Fuerza":"08.jpg","El Ermitaño":"09.jpg","La Rueda de la Fortuna":"10.jpg","La Justicia":"11.jpg","El Colgado":"12.jpg","La Muerte":"13.jpg","La Templanza":"14.jpg","El Diablo":"15.jpg","La Torre":"16.jpg","La Estrella":"17.jpg","La Luna":"18.jpg","El Sol":"19.jpg","El Juicio":"20.jpg","El Mundo":"21.jpg"};function sacarUnaCarta(){const a=Math.floor(Math.random()*arcanosMayores.length);return arcanosMayores[a]}function sacarTriada(){const a=[...arcanosMayores],r=[];for(let e=0;e<3;e++){const e=Math.floor(Math.random()*a.length);r.push(a.splice(e,1)[0])}return r}const resultado=document.getElementById("resultado");let currentTarotLang="de";const tarotFolders={de:"tarot_deutsch",en:"tarot_english"};let lastDrawType=null,lastCards=null;function crearCartaHTML(a){const r=imagenesCartas[a]||"reverse.webp",e=`carta-${Math.random().toString(36).substr(2,9)}`,t=tarotFolders[currentTarotLang]||tarotFolders.de;return console.log("Usando carpeta:",t,"para carta:",a),`\n    <div class="tarot-card" id="${e}">\n      <div class="card-inner">\n        <div class="card-side card-front">\n          <img src="${t}/${r}" alt="${a}">\n        </div>\n        <div class="card-side card-back">\n          <img src="imagenes/reverso.jpg" alt="Reverso">\n        </div>\n      </div>\n    </div>\n  `}function renderUnaCarta(a){resultado.innerHTML=crearCartaHTML(a),agregarVolteo()}function renderTriada(a){resultado.innerHTML=a.map(a=>crearCartaHTML(a)).join(""),agregarVolteo()}function agregarVolteo(){document.querySelectorAll(".tarot-card").forEach(a=>{const r=()=>{a.classList.add("flipped"),a.removeEventListener("click",r)};a.addEventListener("click",r)})}document.getElementById("una-carta").addEventListener("click",()=>{const a=sacarUnaCarta();lastDrawType="one",lastCards=a,renderUnaCarta(a)}),document.getElementById("triada").addEventListener("click",()=>{const a=sacarTriada();lastDrawType="triad",lastCards=a,renderTriada(a)}),document.addEventListener("click",a=>{const r=a.target.closest(".lang-button");if(!r)return;const e=r.dataset.lang;"de"!==e&&"en"!==e||(currentTarotLang=e,console.log("Idioma del tarot ahora:",currentTarotLang),"one"===lastDrawType&&lastCards?renderUnaCarta(lastCards):"triad"===lastDrawType&&Array.isArray(lastCards)?renderTriada(lastCards):resultado.innerHTML="")});